import java.util.*;
import java.io.*;

public class Main {
    static final long INF = (long)1e15;
    static List<Long> pattern = new ArrayList<>(Arrays.asList(0L));
    static int minimal_moves = 1000010;

    static void dfs(long x, int count) {
        if (count > minimal_moves)
            return;
        if (x == 0) {
            minimal_moves = count;
            return;
        }
        int idx = Collections.binarySearch(pattern, x);
        int it_lower_idx;
        if (idx >= 0) {
            it_lower_idx = idx;
        } else {
            it_lower_idx = -idx - 1;
        }
        int it_upper_idx = Collections.binarySearch(pattern, x);
        if (it_upper_idx >= 0) {
            it_upper_idx = it_upper_idx + 1;
        } else {
            it_upper_idx = -it_upper_idx - 1;
        }
        if (it_lower_idx == it_upper_idx) {
            it_lower_idx--;
        }
        long it_lower = pattern.get(it_lower_idx);
        long it_upper = pattern.get(it_upper_idx);
        long diff_a = x - it_lower;
        int cost = it_lower_idx;
        long diff_b = it_upper - x;
        dfs(x % it_lower, count + cost * (x / it_lower));
        dfs(diff_b, count + cost + 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        for (int i = 1; i <= 16; ++i) {
            pattern.add(pattern.get(pattern.size() - 1) * 10 + 1);
        }
        dfs(n, 0);
        System.out.println(minimal_moves);
    }
}
